with flattened as (select id, host, log_ts, level, latency_ms, status_code, k, v from app_logs lateral view explode(context) e as k, v) select case when latency_ms >= 1945 then 'LARGE' else 'SMALL' end as latency_ms_tier, min(log_ts) as first_seen, approx_percentile(latency_ms, array(0.25, 0.5, 0.75)) as latency_ms_quartiles, bit_or(status_code) as status_code_bit_or, count(*) filter (where k = 'trace') as trace_rows, min(log_ts) as started_at, round(avg(latency_ms), 2) as avg_latency_ms from flattened group by rollup (case when latency_ms >= 1945 then 'LARGE' else 'SMALL' end) having bit_or(status_code) > 1 order by status_code_bit_or nulls first;
